/**
 * Build-time content for the marathon plan pages.
 *
 * Sample weeks are generated by the same engine that produces a bought plan,
 * for a fixed reference runner, so the free page can never drift from the
 * product. Follows the pattern of `race-seo-pages.ts`.
 */

import type { Locale, Unit } from '../../types';
import { calculateTimeFromVDOT, calculateVDOT } from '../vdot';
import { describeSession } from './describe';
import { generateMarathonPlan } from './generate';
import { getMarathonCopy, hasMarathonCopy } from './copy';
import { PLAN_LENGTHS, phaseForWeek } from './phases';
import { createResolver, sessionDurationSec } from './resolve';
import { getTier, TIER_IDS, type TierSpec } from './tiers';
import { getSharedCopy, getTierCopy, hasTierCopy } from './tier-copy';
import type { MarathonCopyShared, TierPageCopy } from './tier-copy.en';
import { KM_PER_MILE } from './constants';
import type {
  FitnessEstimate,
  MarathonPaceBand,
  PlanLength,
  TierId,
} from './types';

/**
 * The reference runner for every sample week: a 40:00 10K. Fixed so the
 * published pages are deterministic and so the numbers on them are the same
 * numbers a real buyer of that fitness would receive.
 */
const REFERENCE_RACE = { distanceM: 10_000, timeSec: 2400 };

/**
 * The week shown in full on a tier page. Deliberately a base-phase week: it
 * proves the product without giving away the marathon-specific sessions,
 * which are most of what the plan is worth.
 */
const SAMPLE_WEEK = 5;
/** The length whose shape the volume curve illustrates. */
const SHOWCASE_LENGTH: PlanLength = 18;

function referenceFitness(): FitnessEstimate {
  const vdot = calculateVDOT(REFERENCE_RACE.distanceM, REFERENCE_RACE.timeSec);
  return {
    vdot,
    fiveKEquivalentSec: calculateTimeFromVDOT(vdot, 5000),
    source: 'race',
    updatedAt: '2026-01-01T00:00:00Z',
    setAtWeek: 1,
  };
}

export interface SampleDay {
  /** Monday = 0. */
  dayIndex: number;
  kindLabel: string;
  isQuality: boolean;
  /** Rendered session, or the easy-run distance. */
  detail: string;
  durationMin?: number;
  why?: string;
  substitutions: string[];
  /** Perceived-effort target and its cue. */
  rpe?: { target: string; note: string };
  /** The session offered instead, when the prescribed one needs an event. */
  alternative?: { detail: string; reason: string };
}

export interface SampleWeek {
  weekNumber: number;
  phaseLabel: string;
  volumeKm: number;
  volumeMi: number;
  days: SampleDay[];
}

export interface VolumePoint {
  weekNumber: number;
  phase: string;
  phaseLabel: string;
  km: number;
  mi: number;
  isDeload: boolean;
  isTestWeek: boolean;
}

export interface MarathonTierPage {
  locale: Locale;
  tier: TierId;
  slug: string;
  copy: TierPageCopy;
  spec: TierSpec;
  peakKm: number;
  peakMi: number;
  bandKm: [number, number];
  bandMi: [number, number];
  lengths: readonly PlanLength[];
  /** Volume across the 18-week build, for the chart. */
  volumeCurve: VolumePoint[];
  sampleWeek: SampleWeek;
  /** Marathon pace the reference runner would be given. */
  referenceMp: MarathonPaceBand;
  referenceRaceLabel: string;
}

const toMiles = (km: number): number => +(km / KM_PER_MILE).toFixed(0);

function buildSampleWeek(
  tier: TierId,
  locale: Locale,
  unit: Unit,
): { week: SampleWeek; mp: MarathonPaceBand; curve: VolumePoint[] } {
  const fitness = referenceFitness();
  const copy = getMarathonCopy(locale);
  const plan = generateMarathonPlan({
    tier,
    lengthWeeks: SHOWCASE_LENGTH,
    unit,
    fitness,
  });
  const resolver = createResolver(fitness, plan.mp);

  const curve: VolumePoint[] = plan.weeks.map((w) => ({
    weekNumber: w.weekNumber,
    phase: w.phase,
    phaseLabel: copy[`week.label.${w.phase}`],
    km: Math.round(w.volumeM / 1000),
    mi: toMiles(w.volumeM / 1000),
    isDeload: w.isDeload,
    isTestWeek: w.isTestWeek,
  }));

  const source = plan.weeks.find((w) => w.weekNumber === SAMPLE_WEEK);
  if (!source) throw new Error(`No week ${SAMPLE_WEEK} in the sample plan.`);

  const days: SampleDay[] = source.days.map((day) => {
    const detail = day.segments
      ? describeSession(day.segments, resolver, unit, copy)
      : day.kind === 'rest'
        ? copy['day.rest']
        : `${(day.targetDistanceM / 1000).toFixed(1)} km ${copy['anchor.easy']}`;
    return {
      dayIndex: day.dayIndex,
      kindLabel: copy[`day.${day.kind}`],
      isQuality: day.isQuality,
      detail,
      durationMin: day.segments
        ? Math.round(sessionDurationSec(day.segments, resolver) / 60)
        : undefined,
      why: day.whyKey ? copy[day.whyKey as keyof typeof copy] : undefined,
      substitutions: (day.substitutionKeys ?? []).map(
        (key) => copy[key as keyof typeof copy],
      ),
      rpe: day.rpe
        ? {
            target: day.rpe.target,
            note: copy[day.rpe.noteKey as keyof typeof copy],
          }
        : undefined,
      alternative: day.alternative
        ? {
            detail: describeSession(
              day.alternative.segments,
              resolver,
              unit,
              copy,
            ),
            reason: copy[day.alternative.reasonKey as keyof typeof copy],
          }
        : undefined,
    };
  });

  return {
    week: {
      weekNumber: source.weekNumber,
      phaseLabel: copy[`week.label.${source.phase}`],
      volumeKm: Math.round(source.volumeM / 1000),
      volumeMi: toMiles(source.volumeM / 1000),
      days,
    },
    mp: plan.mp,
    curve,
  };
}

function buildTierPage(locale: Locale, tier: TierId): MarathonTierPage {
  const spec = getTier(tier);
  const copy = getTierCopy(locale)[tier];
  const { week, mp, curve } = buildSampleWeek(tier, locale, 'km');
  return {
    locale,
    tier,
    slug: copy.slug,
    copy,
    spec,
    peakKm: spec.nominalKm,
    peakMi: toMiles(spec.nominalKm),
    bandKm: [spec.bandMinKm, spec.bandMaxKm],
    bandMi: [toMiles(spec.bandMinKm), toMiles(spec.bandMaxKm)],
    lengths: PLAN_LENGTHS,
    volumeCurve: curve,
    sampleWeek: week,
    referenceMp: mp,
    referenceRaceLabel: '40:00 10K',
  };
}

const ALL_LOCALES: Locale[] = ['en', 'es', 'ko', 'de', 'fr'];

/**
 * A locale only gets marathon pages once *both* its plan copy and its
 * sales copy exist. Half-translated pages under a localized URL are worse
 * than no page at all, for readers and for search engines alike.
 */
export const MARATHON_LOCALES: Locale[] = ALL_LOCALES.filter(
  (locale) => hasMarathonCopy(locale) && hasTierCopy(locale),
);

const TIER_PAGES: Partial<Record<Locale, MarathonTierPage[]>> = {};

for (const locale of MARATHON_LOCALES) {
  TIER_PAGES[locale] = TIER_IDS.map((tier) => buildTierPage(locale, tier));
}

export function getMarathonTierPages(locale: Locale): MarathonTierPage[] {
  return TIER_PAGES[locale] ?? [];
}

export function getMarathonTierPage(
  locale: Locale,
  slug: string,
): MarathonTierPage | undefined {
  return getMarathonTierPages(locale).find((p) => p.slug === slug);
}

export function getMarathonTierPageByTier(
  locale: Locale,
  tier: TierId,
): MarathonTierPage | undefined {
  return getMarathonTierPages(locale).find((p) => p.tier === tier);
}

/** The same tier's slug in another locale, for hreflang alternates. */
export function getTierAlternateSlug(
  tier: TierId,
  locale: Locale,
): string | undefined {
  return getMarathonTierPageByTier(locale, tier)?.slug;
}

export interface MarathonIndexPage {
  locale: Locale;
  slug: string;
  shared: MarathonCopyShared;
  tiers: MarathonTierPage[];
}

export function getMarathonIndexPage(
  locale: Locale,
): MarathonIndexPage | undefined {
  if (!MARATHON_LOCALES.includes(locale)) return undefined;
  const shared = getSharedCopy(locale);
  return {
    locale,
    slug: shared.indexSlug,
    shared,
    tiers: getMarathonTierPages(locale),
  };
}

// ---------------------------------------------------------------------------
// Structured data
// ---------------------------------------------------------------------------

/**
 * Product + Offer for a tier page. The free tools elsewhere on the site
 * declare a price of 0; these must not, so the two are kept separate.
 */
export function createTierStructuredData(
  page: MarathonTierPage,
  priceAmount: number,
  currency: string,
  siteUrl = 'https://norwegian-singles.app',
): Record<string, unknown>[] {
  const url = `${siteUrl}/${page.locale}/${page.slug}/`;
  return [
    {
      '@context': 'https://schema.org',
      '@type': 'Product',
      name: `${page.copy.name} — Norwegian Singles marathon plan`,
      description: page.copy.description,
      url,
      brand: { '@type': 'Brand', name: 'Norwegian Singles' },
      category: 'Sports & Recreation > Training Plans',
      offers: {
        '@type': 'Offer',
        price: String(priceAmount),
        priceCurrency: currency,
        availability: 'https://schema.org/InStock',
        url,
      },
    },
  ];
}

/** FAQPage for the hub, from the shared copy. */
export function createMarathonFaqStructuredData(
  page: MarathonIndexPage,
): Record<string, unknown>[] {
  return [
    {
      '@context': 'https://schema.org',
      '@type': 'FAQPage',
      mainEntity: page.shared.faq.map((item) => ({
        '@type': 'Question',
        name: item.q,
        acceptedAnswer: { '@type': 'Answer', text: item.a },
      })),
    },
  ];
}
